<!DOCTYPE html><html><head><meta charset="UTF-8"><title>My Books Report</title><style>body{font-family:Arial,sans-serif;color:#172033;padding:24px}h1{margin-bottom:4px}p{color:#667085;margin-top:0}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #ccd3df;padding:8px;text-align:left;font-size:11px}th{background:#eef2f7;text-transform:uppercase}.meta{display:flex;justify-content:space-between}@media print{button{display:none}body{padding:0}}</style></head><body><div class="meta"><div><h1>My Book Catalogue</h1><p>College Street Online · Generated {{ now()->format('d M Y, h:i A') }}</p></div>@if($mode!=='excel')<button onclick="window.print()">{{ $mode==='pdf'?'Save as PDF':'Print report' }}</button>@endif</div><table><thead><tr><th>Title</th><th>ISBN</th><th>Author</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th></tr></thead><tbody>@foreach($books as $book)<tr><td>{{ $book->title }}</td><td>{{ $book->isbn }}</td><td>{{ $book->author?->name ?? '—' }}</td><td>{{ $book->category?->name ?? 'General' }}</td><td>₹{{ number_format($book->price,2) }}</td><td>{{ $book->inventory?->quantity ?? 0 }}</td><td>{{ ucfirst($book->status) }}</td></tr>@endforeach</tbody></table>@if(in_array($mode,['print','pdf']))<script>window.addEventListener('load',()=>window.print())</script>@endif</body></html>
